import { encodeOpenMediaId, formatMediaDuration } from './open-media';
import { OPEN_BROWSE_CATEGORIES, type OpenBrowseCategory } from './open-browse-categories';

export { OPEN_BROWSE_CATEGORIES, type OpenBrowseCategory };

export interface CuratedEpisode {
  readonly title: string;
  readonly url: string;
}

export interface CuratedOpenVideo {
  slug: string;
  zhTitle: string;
  enTitle: string;
  aliases: readonly string[];
  category: Exclude<OpenBrowseCategory, 'all'>;
  year: string;
  durationSeconds: number;
  poster?: string;
  sourceLabel: string;
  licenceLabel: string;
  summary: string;
  /** 直接可播的官方开放许可 HTTPS 流（国内直连实测 HTTP 200） */
  directPlayUrl?: string;
  /** 可选第二条独立 CDN 直连备用流（自动组装为 $$$ 双线路，支持播放页一键无缝切线） */
  backupDirectPlayUrl?: string;
  /** 可选第二条线路名称 */
  backupSourceLabel?: string;
  /** 多集连播精品剧集/合集（每集均为国内直连实测 HTTP 200/206 流） */
  episodes?: readonly CuratedEpisode[];
  /** 或关联 Internet Archive 馆藏标识符（部署于海外/Render 时经代理直连播放并自动提取字幕） */
  archiveIdentifier?: string;
  /** 或关联美国国会图书馆公版馆藏（itemId|title） */
  locExternalId?: string;
}

export function encodeCuratedVideoVodId(item: CuratedOpenVideo): string {
  if (item.directPlayUrl || (item.episodes && item.episodes.length > 0)) {
    return encodeOpenMediaId('curated', item.slug);
  }
  if (item.archiveIdentifier) {
    return encodeOpenMediaId('archive', item.archiveIdentifier);
  }
  if (item.locExternalId) {
    return encodeOpenMediaId('loc', item.locExternalId);
  }
  return encodeOpenMediaId('curated', item.slug);
}

